import {materials} from '../../core/index.js';import {THREE,mesh,hole,solid,ring,box,roundedRect} from './geometry.js';
function boardShape(){const x=10.5,r=3.3,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2),s=new THREE.Shape();s.moveTo(-7,-22.4);s.lineTo(-x,-19.4);s.lineTo(-x,-12-dy);s.absarc(-8,-12,r,Math.PI+a,Math.PI*3-a,false);s.lineTo(-x,19.4);s.lineTo(-7,22.3);s.lineTo(7,22.3);s.lineTo(x,19.4);s.lineTo(x,-12+dy);s.absarc(8,-12,r,a,Math.PI*2-a,false);s.lineTo(x,-19.4);s.lineTo(7,-22.4);s.lineTo(5.5,-22.4);s.lineTo(5.5,-16.1);s.lineTo(-5.5,-16.1);s.lineTo(-5.5,-22.4);s.closePath();hole(s,0,-12,2.05);for(const x of[-3,-1,1,3])hole(s,x,-15.66,.35);return s;}
export function electronics(host){const metal=materials.metal(0xb4b9a7,{roughness:.45}),pcb=mesh(host.body,solid(boardShape(),.8),materials.plastic(0x2e5943,{roughness:.9}),[0,0,-2.2],'Original U031 own reconstructed1PCB with true boss edge reliefs/Grove notch/contact drills');pcb.userData={role:'physical-pcb',installationInferred:true,notManufacturingBOM:true};const pads=[],solder=[];for(const x of[-3,-1,1,3]){pads.push(mesh(host.body,ring(.62,.35,.05),metal,[x,-15.66,-1.4],'U031 actual J1 through-board annular pad'));solder.push(mesh(host.body,ring(.52,.19,.18),metal,[x,-15.66,-2.38],'U031 actual J1 solder retention collar'));}const chip=box(host.body,[5,5,.8],[0,-6,-1],materials.plastic(0x252a23),'U031 documented MFRC522 hidden package appearance;outline and position inferred'),leads=[];for(const sign of[-1,1])for(let i=0;i<8;i++){const v=(i-3.5)*.5;leads.push(box(host.body,[.7,.25,.1],[sign*2.45,-6+v,-1.35],metal,'U031 inferred MFRC522 QFN32 termination'));leads.push(box(host.body,[.25,.7,.1],[v,-6+sign*2.45,-1.35],metal,'U031 inferred MFRC522 QFN32 termination'));}const regulator=box(host.body,[3.6,2,.7],[6,-4,-1.05],materials.plastic(0x343a2d),'U031 documentary HT7533 hidden envelope/install inferred'),regulatorLeads=[];for(let i=0;i<3;i++)regulatorLeads.push(box(host.body,[.45,.8,.15],[6+(i-1)*1.1,-5.2,-1.325],metal,'U031 HT7533 retained physical lead'));const passives=[],ends=[];for(const[i,[x,y]]of[[-6.4,-6.8],[6.4,-6.8],[-5.8,-1.5],[5.8,-1.5],[0,-1.5]].entries()){passives.push(box(host.body,[1.3,.8,.45],[x,y,-1.175],materials.plastic(i<2?0x353b2f:0xb2a184),'U031 own schematic '+(i<2?'resistor':'capacitor')+' hidden body;no invented value/layout'));for(const sign of[-1,1])ends.push(box(host.body,[.23,.8,.48],[x+sign*.55,y,-1.16],metal,'U031 retained passive metal end'));}const antenna=[],copper=materials.metal(0x9d7a3c,{roughness:.72});for(let n=0;n<3;n++){const w=16-n*1.1,h=24-n*1.1,s=roundedRect(w,h,1.2);s.holes.push(roundedRect(w-.34,h-.34,1.03,{path:new THREE.Path()}));antenna.push(mesh(host.body,solid(s,.035),copper,[0,8,-1.4],'U031 hidden RF loop appearance reconstruction '+(n+1)+';no measured original trace or electrical model'));}return{pcb,pads,solder,chip,leads,regulator,regulatorLeads,passives,ends,antenna};}
